uniform float speed : 0.0 .. 5.0 = 2.0;
uniform float radius : 0.0 .. 1.0 = 0.05;
uniform float radius_gain : 0.0 .. 2.0 = 1.0;
uniform float pulse_gain : 0.0 .. 2.0 = 1.0;
uniform vec3 pulse_color : color = 1.0, 0.2, 0.2;
uniform vec3 background_color : color = 0.2, 0.2, 0.2;

state float ph;
state float pulse;

void update() {
  ph = fract(ph + dt * speed);
  pulse = pulse + dt * (0.0 - pulse) * 2.0; // smooth decay (gain 2)
}

vec3 shade(Led led) {
  fixed r = fixed(length(led.pos.xz));
  fixed dist = fixed(led.s);

  // background radial gradient (darker at centre)
  fixed bg = mix(fixed(1.0), fixed(0.0), clamp(r * fixed(radius) * fixed(4.0), fixed(0.0), fixed(1.0)));

  // pulse edge: distance from center to this led, compared to expanding radius
  fixed edge = abs(r - pulse * fixed(radius) * fixed(radius_gain));
  fixed pulse_edge = smoothstep(fixed(0.02), fixed(0.0), fixed(1.0) - edge);

  // combine
  fixed val = mix(bg, fixed(1.0), pulse_edge * fixed(pulse_gain));

  // apply colors
  vec3 col = mix(background_color, pulse_color, val);
  return col;
}
